insert into private.questions(id,level,accepted,explanation) values ('stone',1,'["Палеолит"]'::jsonb,'Палеолит — ежелгі тас ғасыры. Одан кейін мезолит, содан соң неолит келеді.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('bronze',2,'["Геометриялық өрнекті қыш ыдыс"]'::jsonb,'Сызба геометриялық өрнекті қыш ыдысты көрсетеді. Мұндай ыдыстар кітапта Андронов мәдениетінің белгілерінің бірі ретінде сипатталған; тек өрнекке қарап кез келген олжаның дәуірін дәл анықтауға болмайды.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('saka',3,'["Жетісу"]'::jsonb,'Бесшатыр мен Есік — Жетісу ескерткіштері. Карта аймақтарды шартты түрде көрсетеді; тарихи мемлекет шекаралары берілмеген.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('hun',4,'["шаньюй","шань юй"]'::jsonb,'Мөде шаньюй деп аталған. Кітапта оның билігі ғұн мемлекетінің қалыптасуы мен күшеюіне қатысты баяндалады.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('turk',5,'[["Тас дәуірі","Қола дәуірі","Түрік қағанаты"]]'::jsonb,'Дұрыс рет: Тас дәуірі → Қола дәуірі → Түрік қағанаты. Түрік қағанатының құрылуы кітапта 552 жылмен байланыстырылады.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('turgesh',6,'["Сұлық","Сұлу"]'::jsonb,'Бұл атау Сұлық қағанға қатысты берілген. Оқулық оны арабтарға тойтарыс беруімен байланыстырады.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('karluk',7,'[["Алтайдың батысы","Жетісу"]]'::jsonb,'Қарлұқтардың сипатталған қонысы — Алтайдың батысы; Бесшатыр мен Есік — Жетісу. Бұл халықтардың барлық уақытта тек бір аймақта өмір сүргенін білдірмейді.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('karakhan',8,'["Боғра","Богра"]'::jsonb,'Сатұқ Боғра хан. Даталар жөніндегі пікір айырмашылығына байланысты бұл тапсырма жылды сұрамайды.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('horde',9,'[["Сайын хан","Шаньюй","Сүзеген"]]'::jsonb,'Бату — Сайын хан; Мөде — шаньюй; Сұлық — сүзеген. Атақ пен лақап атаудың мағынасы бірдей емес.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
insert into private.questions(id,level,accepted,explanation) values ('kazakh',10,'["Жәнібек","Жанибек","Жәнібек хан"]'::jsonb,'Керей мен Жәнібек Қазақ хандығының негізін қалаушы хандар ретінде танылады. Бұл бөлім PDF-тің 163-бетінде, кітаптың баспа бойынша 164-бетінде басталады.') on conflict(id) do update set accepted=excluded.accepted, explanation=excluded.explanation;
